CREATE TABLE USUARIO (ID_USUARIO NUMBER GENERATED BY DEFAULT AS IDENTITY, NM_USUARIO VARCHAR2(100) NOT NULL, DS_EMAIL VARCHAR2(150) NOT NULL, NR_PONTOS NUMBER DEFAULT 0 NOT NULL, NR_PONTOS_RESGATADOS NUMBER DEFAULT 0 NOT NULL, DS_SENHA_HASH VARCHAR2(60), DS_PERFIL VARCHAR2(5) DEFAULT 'USER' NOT NULL CHECK (DS_PERFIL IN ('USER','ADMIN')), ST_ATIVO NUMBER(1) DEFAULT 0 NOT NULL CHECK (ST_ATIVO IN (0,1)), NR_TOKEN_VERSION NUMBER(19) DEFAULT 0 NOT NULL, NR_VERSAO NUMBER(19) DEFAULT 0 NOT NULL, CONSTRAINT PK_USUARIO PRIMARY KEY (ID_USUARIO), CONSTRAINT UK_USUARIO_EMAIL UNIQUE (DS_EMAIL), CONSTRAINT CK_USUARIO_PONTOS CHECK (NR_PONTOS >= 0), CONSTRAINT CK_USUARIO_RESGATADOS CHECK (NR_PONTOS_RESGATADOS >= 0));
CREATE TABLE ACAO (ID_ACAO NUMBER GENERATED BY DEFAULT AS IDENTITY, NM_ACAO VARCHAR2(100) NOT NULL, NR_PONTOS NUMBER(3) NOT NULL, NR_VERSAO NUMBER(19) DEFAULT 0 NOT NULL, CONSTRAINT PK_ACAO PRIMARY KEY (ID_ACAO), CONSTRAINT CK_ACAO_PONTOS CHECK (NR_PONTOS BETWEEN 1 AND 100));
CREATE TABLE RECOMPENSA (ID_RECOMPENSA NUMBER GENERATED BY DEFAULT AS IDENTITY, NM_RECOMPENSA VARCHAR2(100) NOT NULL, DS_RECOMPENSA VARCHAR2(200), NR_CUSTO NUMBER NOT NULL, NR_ESTOQUE NUMBER DEFAULT 0 NOT NULL, DS_CATEGORIA VARCHAR2(30), ST_DESTAQUE VARCHAR2(20), NR_VERSAO NUMBER(19) DEFAULT 0 NOT NULL, CONSTRAINT PK_RECOMPENSA PRIMARY KEY (ID_RECOMPENSA), CONSTRAINT CK_RECOMPENSA_CUSTO CHECK (NR_CUSTO > 0), CONSTRAINT CK_RECOMPENSA_ESTOQUE CHECK (NR_ESTOQUE >= 0));
CREATE TABLE HISTORICO (ID_HISTORICO NUMBER GENERATED BY DEFAULT AS IDENTITY, ID_USUARIO NUMBER NOT NULL, DS_ACAO VARCHAR2(150) NOT NULL, NR_PONTOS NUMBER(3) NOT NULL, DT_ACAO TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, NR_VERSAO NUMBER(19) DEFAULT 0 NOT NULL, CONSTRAINT PK_HISTORICO PRIMARY KEY (ID_HISTORICO), CONSTRAINT FK_HISTORICO_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES USUARIO (ID_USUARIO), CONSTRAINT CK_HISTORICO_PONTOS CHECK (NR_PONTOS BETWEEN 0 AND 100));
CREATE TABLE SELO (ID_SELO NUMBER GENERATED BY DEFAULT AS IDENTITY, NM_SELO VARCHAR2(100) NOT NULL, DS_SELO VARCHAR2(200), NR_PONTOS_MIN NUMBER DEFAULT 0 NOT NULL, NR_VERSAO NUMBER(19) DEFAULT 0 NOT NULL, CONSTRAINT PK_SELO PRIMARY KEY (ID_SELO), CONSTRAINT CK_SELO_PONTOS_MIN CHECK (NR_PONTOS_MIN >= 0));
CREATE TABLE CARTA (ID_CARTA NUMBER GENERATED BY DEFAULT AS IDENTITY, NM_CARTA VARCHAR2(100) NOT NULL, DS_CARTA VARCHAR2(200), NM_CONJUNTO VARCHAR2(60) NOT NULL, DS_RARIDADE VARCHAR2(30) NOT NULL, NR_VERSAO NUMBER(19) DEFAULT 0 NOT NULL, CONSTRAINT PK_CARTA PRIMARY KEY (ID_CARTA), CONSTRAINT CK_CARTA_RARIDADE CHECK (DS_RARIDADE IN ('COMUM', 'INCOMUM', 'RARA', 'EPICA', 'LENDARIA')));
CREATE TABLE USUARIO_CARTA (ID_USUARIO NUMBER NOT NULL, ID_CARTA NUMBER NOT NULL, QT_CARTA NUMBER DEFAULT 1 NOT NULL, NR_VERSAO NUMBER(19) DEFAULT 0 NOT NULL, CONSTRAINT PK_USUARIO_CARTA PRIMARY KEY (ID_USUARIO, ID_CARTA), CONSTRAINT FK_US_CARTA_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES USUARIO (ID_USUARIO), CONSTRAINT FK_US_CARTA_CARTA FOREIGN KEY (ID_CARTA) REFERENCES CARTA (ID_CARTA), CONSTRAINT CK_US_CARTA_QT CHECK (QT_CARTA > 0));
CREATE TABLE USUARIO_FRAGMENTO (ID_USUARIO NUMBER NOT NULL, DS_RARIDADE VARCHAR2(30) NOT NULL, QT_FRAGMENTOS NUMBER DEFAULT 0 NOT NULL, NR_VERSAO NUMBER(19) DEFAULT 0 NOT NULL, CONSTRAINT PK_USUARIO_FRAGMENTO PRIMARY KEY (ID_USUARIO, DS_RARIDADE), CONSTRAINT FK_UF_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES USUARIO (ID_USUARIO), CONSTRAINT CK_UF_QT CHECK (QT_FRAGMENTOS >= 0));
CREATE TABLE AUTH_LOGIN_ATTEMPT (DS_KEY VARCHAR2(64) PRIMARY KEY, NR_WINDOW NUMBER(19) NOT NULL, NR_ATTEMPTS NUMBER(10) NOT NULL);
CREATE TABLE AUTH_BOOTSTRAP_LOCK (ID_LOCK NUMBER(1) PRIMARY KEY);
